#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_layer_zero_stats_accumulation() {
        clear_accumulated_features();
        set_accumulation(true);

        let dummy_input = [0i16; Board::TOTAL_FN];
        mlp_inference(&dummy_input);

        let stats = take_accumulated_layer_zero_stats();
        assert!(stats.count >= 1);
        assert_eq!(
            stats.layer_sizes,
            [Board::TOTAL_FN, M_B1.len(), M_B2.len(), M_B3.len(), M_B4.len()]
        );
        assert!(stats.zero_counts[0] >= Board::TOTAL_FN);
        assert_eq!(stats.zero_percentage(0), 100.0);

        clear_accumulated_features();
    }

    #[test]
    fn test_mlp_inference_eval_sanity() {
        let dummy = [0i16; Board::TOTAL_FN];
        let score = mlp_inference(&dummy);
        assert!(score >= -6000 && score <= 6000);

        let mut test_input = [0i16; Board::TOTAL_FN];
        test_input[0] = 1;
        test_input[3] = -2;
        test_input[10] = 3;
        test_input[154] = 2;
        let score2 = mlp_inference(&test_input);
        assert!(score2 >= -6000 && score2 <= 6000);
    }
}
